package com.nextfeet.nextfeet.cart; import java.util.*; import java.math.*; import org.springframework.jdbc.core.*; import org.springframework.stereotype.Repository; import com.nextfeet.nextfeet.model.Zapatilla; @Repository public class CarritoRepository implements CarritoDAO {private final JdbcTemplate db; public CarritoRepository(JdbcTemplate db){this.db=db;} private Integer carrito(Integer u){List<Integer> x=db.query("select id from carrito where usuario_id=?",(r,n)->r.getInt(1),u); if(x.isEmpty()){db.update("insert into carrito(usuario_id) values(?)",u);return db.queryForObject("select id from carrito where usuario_id=?",Integer.class,u);}return x.get(0);} public List<Zapatilla> listar(Integer u){Integer c=carrito(u);return db.query("select z.*,ci.talla,ci.cantidad from carrito_item ci join zapatilla z on z.id=ci.zapatilla_id where ci.carrito_id=?",(r,n)->{Zapatilla z=new Zapatilla();z.setId(r.getInt("id"));z.setNombre(r.getString("nombre"));z.setPrecio(r.getBigDecimal("precio"));z.setTalla(r.getString("talla"));z.setCantidad(r.getInt("cantidad"));z.setMarca(r.getString("marca"));return z;},c);} public void agregar(Integer u,Integer z,String t,int q){Integer c=carrito(u);Integer n=db.query("select cantidad from carrito_item where carrito_id=? and zapatilla_id=? and talla=?", (r,rowNum)->r.getInt(1), c,z,t).stream().findFirst().orElse(null);if(n==null)db.update("insert into carrito_item(carrito_id,zapatilla_id,talla,cantidad) values(?,?,?,?)",c,z,t,q);else actualizar(u,z,t,n+q);} public void actualizar(Integer u,Integer z,String t,int q){Integer c=carrito(u);db.update("update carrito_item set cantidad=? where carrito_id=? and zapatilla_id=? and talla=?",q,c,z,t);} public void eliminar(Integer u,Integer z,String t){db.update("delete from carrito_item where carrito_id=? and zapatilla_id=? and talla=?",carrito(u),z,t);} public void vaciar(Integer u){db.update("delete from carrito_item where carrito_id=?",carrito(u));} public BigDecimal total(Integer u){Integer c=carrito(u);return db.queryForObject("select coalesce(sum(ci.cantidad*z.precio),0) from carrito_item ci join zapatilla z on z.id=ci.zapatilla_id where ci.carrito_id=?",BigDecimal.class,c);}}